def count(actual, predicted, labels):
    if len(actual) != len(predicted) or len(labels) != len(set(labels)):
        raise ValueError('inputs')
    names = sorted(set(labels) | set(actual) | set(predicted))
    indices = {name: i for i, name in enumerate(names)}
    matrix = [[0] * len(names) for _ in names]
    for actual_label, predicted_label in zip(actual, predicted):
        matrix[indices[actual_label]][indices[predicted_label]] += 1
    return names, matrix


def merge(left, right):
    names = sorted(set(left[0]) | set(right[0]))
    indices = {name: i for i, name in enumerate(names)}
    matrix = [[0] * len(names) for _ in names]
    for labels, values in (left, right):
        positions = [indices[label] for label in labels]
        for i, row_index in enumerate(positions):
            for j, column_index in enumerate(positions):
                matrix[row_index][column_index] += values[i][j]
    return names, matrix

from core import count, merge


def solve(p):
    state = count([], [], p['labels'])
    for shard in p['shards']:
        state = merge(state, count(shard['actual'], shard['predicted'], []))
    labels, matrix = state
    scores = []
    for i in range(len(labels)):
        denominator = sum(matrix[i]) + sum(row[i] for row in matrix)
        scores.append(2 * matrix[i][i] / denominator if denominator else 0.0)
    return {
        'labels': labels,
        'matrix': matrix,
        'macro_f1': sum(scores) / len(labels) if labels else 0.0,
    }
